import{_ as r,C as a,c as s,o as i,a3 as e,G as n}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Lots and serial numbers","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/tracking/lots-and-serial-numbers.md","filePath":"master/supply-chain/inventories/tracking/lots-and-serial-numbers.md","lastUpdated":1792041590000}'),l={name:"master/supply-chain/inventories/tracking/lots-and-serial-numbers.md"};function g(d,t,c,u,h,p){const o=a("ImagePopup");return i(),s("div",null,[t[0]||(t[0]=e('<h1 id="lots-and-serial-numbers" tabindex="-1">Lots and serial numbers <a class="header-anchor" href="#lots-and-serial-numbers" aria-label="Permalink to &quot;Lots and serial numbers&quot;">​</a></h1><p>A lot is one batch of identical goods made or bought together. A serial number is a code that belongs to exactly one unit. Use them when you must trace goods back to the vendor or forward to the customer, for example for recalls or warranty.</p><blockquote><p><strong>In simple words:</strong> Lot means &quot;these 250 tablets share a label&quot;. Serial means &quot;this one laptop has its own label&quot;.</p></blockquote><table tabindex="0"><thead><tr><th></th><th>Lot</th><th>Serial number</th></tr></thead><tbody><tr><td>Units per number</td><td>Many</td><td>One</td></tr><tr><td>Example</td><td>MC-VITC-001, 250 tablets</td><td>SN-00045, one laptop</td></tr><tr><td><strong>Track By</strong> option</td><td><strong>By Lots</strong></td><td><strong>By Unique Serial Number</strong></td></tr></tbody></table><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Go to <code>Inventory → Settings → Manage Traceability</code> and turn on <strong>Lots &amp; Serial Numbers</strong>. Then click <strong>Save changes</strong>. This reveals <code>Inventory → Products → Lots / Serial Numbers</code> and the <strong>Track By</strong> field on products. <strong>Display on Delivery Slips</strong> is off by default. Turn it on to print the numbers on the slip.</p>',6)),n(o,{src:"/images1/inventory/lot_setting_on.png",alt:"Manage Traceability with Lots & Serial Numbers on and Display on Delivery Slips switched on but not yet saved (it is off by default)"}),t[1]||(t[1]=e('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>You cannot turn the setting off while products with tracking still hold stock. Switch off tracking on every such product first, then save.</p></div><h2 id="track-a-product-by-lot-or-serial" tabindex="-1">Track a product by lot or serial <a class="header-anchor" href="#track-a-product-by-lot-or-serial" aria-label="Permalink to &quot;Track a product by lot or serial&quot;">​</a></h2><ol><li>Open the product in <code>Inventory → Products → Products</code> and click <strong>Edit</strong>.</li><li>Turn on <strong>Track Inventory</strong>.</li><li>Set <strong>Track By</strong> to <strong>By Lots</strong> or <strong>By Unique Serial Number</strong>.</li></ol>',3)),n(o,{src:"/images1/inventory/lot_track_by.png",alt:"Product Inventory section with Track By set to By Lots"}),t[2]||(t[2]=e('<ol start="4"><li>Click <strong>Save changes</strong>.</li></ol><h2 id="allow-numbers-on-an-operation-type" tabindex="-1">Allow numbers on an operation type <a class="header-anchor" href="#allow-numbers-on-an-operation-type" aria-label="Permalink to &quot;Allow numbers on an operation type&quot;">​</a></h2><p>An operation type decides whether numbers can be created or picked. Go to <code>Inventory → Configurations → Warehouse Management → Operation Types</code> and open <strong>Receipts</strong>. In the <strong>Lots/Serial</strong> fieldset:</p><ul><li><strong>Create New:</strong> You type new numbers while receiving.</li><li><strong>Use Existing:</strong> You pick numbers that already exist, or leave the field empty.</li></ul><p>See <a href="./../warehouses/operation-types.html">Operation types</a>.</p><h2 id="assign-numbers-on-a-receipt" tabindex="-1">Assign numbers on a receipt <a class="header-anchor" href="#assign-numbers-on-a-receipt" aria-label="Permalink to &quot;Assign numbers on a receipt&quot;">​</a></h2><ol><li>Open a Ready receipt, such as the one from a purchase order. See <a href="./../operations/receipts.html">Receipts</a>.</li><li>Open the <strong>Edit</strong> tab and go to the <strong>Operations</strong> tab. On the tracked product&#39;s row, click the small list icon next to <strong>Quantity</strong>. Its tooltip reads <strong>Manage Stock Moves</strong>.</li><li>In each line, fill <strong>Lot/Serial Number</strong> (the first column), <strong>Store To</strong> and <strong>Quantity</strong>. To create a new lot on the spot, click the <strong>+</strong> next to the lot field.</li></ol>',7)),n(o,{src:"/images1/inventory/lot_receipt_manage_moves.png",alt:"Manage Stock Moves window with lot MC-VITC-001, Store To WH/Input and quantity 250"}),t[3]||(t[3]=e('<ol start="4"><li>Click <strong>Save</strong>, then <strong>Validate</strong>.</li></ol><p>For serial products, use one line per unit, each with quantity 1.</p><h3 id="generate-or-import-many-numbers" tabindex="-1">Generate or import many numbers <a class="header-anchor" href="#generate-or-import-many-numbers" aria-label="Permalink to &quot;Generate or import many numbers&quot;">​</a></h3><p>For long lists, use the links at the top of the window.</p><ul><li><strong>Generate Serials/Lots:</strong> Fill <strong>First Lot Number</strong>. <strong>Quantity per Lot</strong> and <strong>Quantity Received</strong> are prefilled. Click <strong>Submit</strong>. Aureus fills the line with the lot, quantity and unit, but does not save it. Click <strong>Save</strong>.</li><li><strong>Import Serials/Lots:</strong> Paste into <strong>Lot/Serial Numbers</strong>, one number per line. Click <strong>Submit</strong>, then <strong>Save</strong>.</li><li><strong>Keep current lines:</strong> Turn on this toggle to add to the lines you already have.</li></ul><h2 id="assign-numbers-on-a-delivery" tabindex="-1">Assign numbers on a delivery <a class="header-anchor" href="#assign-numbers-on-a-delivery" aria-label="Permalink to &quot;Assign numbers on a delivery&quot;">​</a></h2><p>Open the delivery, click the list icon (<strong>Manage Stock Moves</strong>) next to <strong>Quantity</strong> and choose <strong>Lot/Serial Number</strong> and <strong>Pick From</strong> for each line. Quantities cannot exceed what that lot holds.</p><p>Validate warnings you may see:</p><ul><li><strong>Supply Lot/Serial Number:</strong> A tracked product has no number. Add one.</li><li><strong>Serial Number Already Assigned:</strong> The serial is used on another line.</li></ul><h2 id="create-a-lot-by-hand" tabindex="-1">Create a lot by hand <a class="header-anchor" href="#create-a-lot-by-hand" aria-label="Permalink to &quot;Create a lot by hand&quot;">​</a></h2><ol><li>Go to <code>Inventory → Products → Lots / Serial Numbers</code>.</li><li>Click <strong>New Lot / Serial Number</strong>.</li></ol>',11)),n(o,{src:"/images1/inventory/lot_create.png",alt:"Create lot form with name MC-VITC-001, product Vitamin C Tablets 500mg and reference, and Company empty"}),t[4]||(t[4]=e('<ul><li><strong><em>Name:</em></strong> Required. The lot or serial code, such as <strong>MC-VITC-001</strong>. The placeholder shows the pattern <strong>LOT/0001/20121</strong>.</li><li><strong><em>Product:</em></strong> Required. The tracked product. It cannot change once the lot has moved.</li><li><strong><em>Company:</em></strong> Owner company. It is empty by default.</li><li><strong><em>Reference:</em></strong> An internal number if it differs from the maker&#39;s code.</li><li><strong><em>Description:</em></strong> Free notes.</li></ul><ol start="3"><li>Click <strong>Create</strong>.</li></ol><h2 id="lot-list-and-view" tabindex="-1">Lot list and view <a class="header-anchor" href="#lot-list-and-view" aria-label="Permalink to &quot;Lot list and view&quot;">​</a></h2><p>The list shows <strong>Name</strong>, <strong>Product</strong>, <strong>Internal Reference</strong> and <strong>On Hand Quantity</strong>. Group by <strong>Product</strong> or <strong>Location</strong>. A lot in use cannot be deleted.</p>',4)),n(o,{src:"/images1/inventory/lot_list.png",alt:"Lots list with Name, Product, Internal Reference and On Hand Quantity"}),t[5]||(t[5]=e("<p>The lot view has the tabs <strong>View</strong>, <strong>Edit</strong> and <strong>Locations</strong>. <strong>Locations</strong> opens a page titled <strong>Manage ... Quantities</strong> (with the lot name). Its columns are <strong>Product</strong>, <strong>Location</strong>, <strong>Storage Category</strong>, <strong>Package</strong>, <strong>On Hand Quantity</strong>, <strong>Unit</strong> and <strong>Delete</strong>. The <strong>On Hand Quantity</strong> cells are editable inputs. The page shows where the lot sits now. It can also show negative stock at <code>Virtual Locations/Inventory Adjustment</code> for the lot.</p>",1)),n(o,{src:"/images1/inventory/lot_view_locations.png",alt:"Lot Locations page with columns Product, Location, Storage Category, Package, On Hand Quantity, Unit and Delete, including negative stock at Virtual Locations/Inventory Adjustment"}),t[6]||(t[6]=e('<h2 id="print-labels" tabindex="-1">Print labels <a class="header-anchor" href="#print-labels" aria-label="Permalink to &quot;Print labels&quot;">​</a></h2><ul><li>On one lot, the header has the buttons <strong>Print</strong> and <strong>Delete</strong>. Click <strong>Print</strong> to download a PDF.</li><li>On the list, tick lots and choose the bulk action <strong>Print Barcode</strong>.</li></ul><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>A lot is a label on a stock quantity. The same product can hold several lots in one location. The <strong>Moves History</strong> and <strong>Locations</strong> reports can group by lot.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./packages.html">Packages</a></li><li><a href="./../products/configure-product.html">Configure a product</a></li><li><a href="./../operations/receipts.html">Receipts</a></li><li><a href="./../operations/stock-moves-and-lots.html">Stock moves and lots</a></li></ul>',6))])}const y=r(l,[["render",g]]);export{b as __pageData,y as default};
